input.script:
services = list_services({})

# Gather all ERROR logs per service for the day (paginated)
per_service = for svc in services {
    first = boundary retry 2 {
        return search_logs({ service: svc, level: "ERROR", page: 1 })
    } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    rest = for page in list.range(2, first.total_pages + 1) {
        r = boundary retry 2 {
            return search_logs({ service: svc, level: "ERROR", page })
        } catch err {
            return fail("PAGE_FAILED", err.code + ": " + err.message)
        }
        return r.items
    }
    items = fold acc = first.items for page in rest {
        return acc + page
    }
    return { service: svc, items }
}

# Per-service hourly histogram + peak hour stats
analyzed = for ps in per_service {
    hours = fold acc = {} for item in ps.items {
        h = text.slice(item.ts, 0, 13)
        return acc + { [h]: (acc[h] if h in acc else 0) + 1 }
    }
    stats = fold acc = { max_hour: "", max_count: 0, total: 0 } for kv in hours {
        bigger = kv.value > acc.max_count
        return {
            max_hour: kv.key if bigger else acc.max_hour,
            max_count: kv.value if bigger else acc.max_count,
            total: acc.total + kv.value
        }
    }
    return {
        service: ps.service,
        items: ps.items,
        hours: hours,
        max_hour: stats.max_hour,
        max_count: stats.max_count,
        total: stats.total
    }
}

# Incident = service with the largest single-hour burst (well above background)
incident = fold acc = { service: "", items: [], hours: {}, max_count: 0, total: 0 } for s in analyzed {
    return s if s.max_count > acc.max_count else acc
}
assert(incident.service != "", "no incident service found")

# Burst start = earliest hour reaching >= half of peak hourly rate
burst_hour = fold acc = "" for kv in incident.hours {
    hit = kv.value * 2 >= incident.max_count and (acc == "" or kv.key < acc)
    return kv.key if hit else acc
}
assert(burst_hour != "", "no burst hour found")

# First error timestamp within the burst hour = spike start
spike_ts = fold acc = "" for item in incident.items {
    hit = text.starts_with(item.ts, burst_hour) and (acc == "" or item.ts < acc)
    return item.ts if hit else acc
}

# Deploy immediately preceding the spike
deploys = boundary retry 2 {
    return get_deploys({ service: incident.service })
} catch err {
    return fail("DEPLOYS_FAILED", err.code + ": " + err.message)
}
chosen = fold acc = { sha: "", at: "" } for d in deploys {
    ok = d.deployed_at <= spike_ts and (acc.at == "" or d.deployed_at > acc.at)
    return { sha: d.sha if ok else acc.sha, at: d.deployed_at if ok else acc.at }
}
assert(chosen.sha != "", "no deploy before spike")

owner = boundary retry 2 {
    return get_service_owners({ service: incident.service })
} catch err {
    return fail("OWNER_FAILED", err.code + ": " + err.message)
}

result = submit_result({ answer: {
    service: incident.service,
    deploy_sha: chosen.sha,
    owner_email: owner.owner_email
} })

return {
    submitted: result.recorded,
    service: incident.service,
    deploy_sha: chosen.sha,
    owner_email: owner.owner_email,
    spike_start: spike_ts,
    peak_hour_count: incident.max_count,
    day_total_errors: incident.total
}
